import { useState, useEffect } from "react";
import BikeCard from "./components/BikeCard";
import Timer from "./components/Timer";

function App() {
  const [studentId, setStudentId] = useState("");
  const [loggedIn, setLoggedIn] = useState(false);
  const [bikes, setBikes] = useState([]);
  const [activeRide, setActiveRide] = useState(null);
  const [summary, setSummary] = useState(null);

 const API_URL = "[localhost](http://localhost:5000)";


  // Fetch available bikes
  const fetchBikes = async () => {
    const res = await fetch(`${API_URL}/bikes`);
    const data = await res.json();
    setBikes(data);
  };

  useEffect(() => {
    fetchBikes();
  }, []);

  // Login Simulation
  const handleLogin = () => {
    if (!studentId.trim()) return;
    setLoggedIn(true);
  };

  // Unlock a bike
  const unlockBike = async (bikeId) => {
    const res = await fetch(`${API_URL}/unlock`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ studentId, bikeId }),
    });

    const data = await res.json();

    if (res.ok) {
      setActiveRide({
        rideId: data.rideId,
        bikeId,
        startTime: Date.now(),
      });
      fetchBikes();
    } else {
      alert(data.error);
    }
  };

  // Return bike
  const returnBike = async () => {
    const res = await fetch(`${API_URL}/return`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ rideId: activeRide.rideId }),
    });

    const data = await res.json();

    if (res.ok) {
      setSummary({
        duration: data.duration,
        cost: data.cost,
      });
      setActiveRide(null);
      fetchBikes();
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      {!loggedIn ? (
        <div className="max-w-lg mx-auto mt-20 bg-white p-6 rounded shadow">
          <h1 className="text-2xl font-bold mb-4 text-blue-700">HFT Bike Sharing</h1>
          <input
            className="border w-full p-2 rounded mb-3"
            placeholder="Enter Student ID"
            value={studentId}
            onChange={(e) => setStudentId(e.target.value)}
          />
          <button
            onClick={handleLogin}
            className="bg-blue-600 text-white px-4 py-2 w-full rounded"
          >
            Login
          </button>
        </div>
      ) : (
        <div>
          <h2 className="text-xl font-semibold mb-4">Available Bikes</h2>
          
          {activeRide && (
            <div className="bg-green-100 border border-green-400 p-4 rounded mb-6">
              <p className="font-semibold">You are currently riding Bike #{activeRide.bikeId}</p>
              <Timer startTime={activeRide.startTime} />
              <button
                onClick={returnBike}
                className="bg-red-600 text-white px-4 py-2 mt-3 rounded"
              >
                Return Bike
              </button>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {bikes.map((b) => (
              <BikeCard key={b._id} bike={b} unlockBike={unlockBike} />
            ))}
          </div>

          {summary && (
            <div className="fixed inset-0 bg-black bg-opacity-40 flex justify-center items-center">
              <div className="bg-white p-6 rounded shadow-lg w-80">
                <h2 className="text-xl font-bold mb-3">Ride Summary</h2>
                <p>Duration: {summary.duration} min</p>
                <p>Total Cost: €{summary.cost.toFixed(2)}</p>
                <button
                  onClick={() => setSummary(null)}
                  className="mt-4 bg-blue-600 text-white px-4 py-2 rounded"
                >
                  Close
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default App;
